 * @throws {LogError} on the first line the grammar refuses.
 */
export function parse(lines, policy) {
  const jobs = new Map()
  const submissions = []
  const submitted = new Set()

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const rawLine = lines[lineNum]
    const line = lineNum + 1 // 1-based line number
    const text = rawLine.trim()

    // Skip empty lines and comments
    if (text === '' || text.startsWith('#')) continue

    const words = text.split(/\s+/u)
    if (words.length === 0) continue

    const directive = words[0]

    // Try to parse as policy directive
    if (policyDirective(line, words, policy)) continue

    // Parse job directive
    if (directive === 'job') {
      if (words.length < 4) throw new LogError(line, 'expected job <id> <duration> <outcome>...')

      const id = words[1]
      const duration = positive(line, 'duration', words[2])

      // Validate job id
      if (!ID.test(id)) throw new LogError(line, `invalid job id ${id}`)

      // Check if job is declared twice
      if (jobs.has(id)) throw new LogError(line, `job ${id} is declared twice`)

      // Parse outcomes
      const outcomes = words.slice(3)
      for (const outcome of outcomes) {
        if (outcome !== 'ok' && outcome !== 'fail') throw new LogError(line, `invalid outcome ${outcome}`)
      }

      jobs.set(id, { id, duration, outcomes })
      continue
    }

    // Parse submit directive
    if (directive === 'submit') {
      if (words.length !== 3) throw new LogError(line, 'expected submit <at> <id>')

      const at = count(line, 'at', words[1])
      const id = words[2]

      // Check if job is submitted twice
      if (submitted.has(id)) throw new LogError(line, `job ${id} is submitted twice`)

      submissions.push({ id, at })
      submitted.add(id)
      continue
    }

    // Unknown directive
    throw new LogError(line, `unknown directive ${directive}`)
  }

  // Validate that all submissions reference declared jobs
  for (const submission of submissions) {
    if (!jobs.has(submission.id)) throw new LogError(0, `unknown job ${submission.id}`)
  }

  return { jobs, submissions }
}"}

